1020	            let scale: CGFloat = 0.8
1021	            let newSize = CGSize(width: current.size.width * scale, height: current.size.height * scale)
1022	            let renderer = UIGraphicsImageRenderer(size: newSize)
1023	            let resized = renderer.image { _ in
1024	                current.draw(in: CGRect(origin: .zero, size: newSize))
