private let ciContext = CIContext()

/// 预处理图片以减少水印干扰
private func preprocessImage(_ image: UIImage) -> UIImage {
    guard let ciImage = CIImage(image: image) else {
        print("[AI Debug] 无法创建CIImage，使用原图")
        return image
    }

    var processedImage = ciImage

    // 1. 增强对比度 - 使文字更清晰，水印更淡
    if let contrastFilter = CIFilter(name: "CIColorControls") {
        contrastFilter.setValue(processedImage, forKey: kCIInputImageKey)
        contrastFilter.setValue(1.15, forKey: kCIInputContrastKey)  // 轻微增强对比度
        contrastFilter.setValue(0.05, forKey: kCIInputBrightnessKey)  // 略微提亮
        contrastFilter.setValue(1.0, forKey: kCIInputSaturationKey)  // 保持饱和度
        if let output = contrastFilter.outputImage {
            processedImage = output
        }
    }

    // 2. 锐化 - 使文字边缘更清晰
    if let sharpenFilter = CIFilter(name: "CISharpenLuminance") {
        sharpenFilter.setValue(processedImage, forKey: kCIInputImageKey)
        sharpenFilter.setValue(0.5, forKey: kCIInputSharpnessKey)
        if let output = sharpenFilter.outputImage {
            processedImage = output
        }
    }

    // 3. 高光恢复 - 使浅色水印更不明显
    if let highlightFilter = CIFilter(name: "CIHighlightShadowAdjust") {
        highlightFilter.setValue(processedImage, forKey: kCIInputImageKey)
        highlightFilter.setValue(0.3, forKey: "inputHighlightAmount")  // 压制高光（水印通常是浅色）
        highlightFilter.setValue(0.0, forKey: "inputShadowAmount")
        if let output = highlightFilter.outputImage {
            processedImage = output
        }
    }

    // 4. 局部对比度增强（使文字更突出）
    if let unsharpMask = CIFilter(name: "CIUnsharpMask") {
        unsharpMask.setValue(processedImage, forKey: kCIInputImageKey)
        unsharpMask.setValue(2.5, forKey: kCIInputRadiusKey)
        unsharpMask.setValue(0.5, forKey: kCIInputIntensityKey)
        if let output = unsharpMask.outputImage {
            processedImage = output
        }
    }

    // 转换回UIImage
    guard let cgImage = ciContext.createCGImage(processedImage, from: processedImage.extent) else {
        print("[AI Debug] 无法创建CGImage，使用原图")
        return image
    }

    print("[AI Debug] 图片预处理完成：对比度增强、锐化、高光压制")
    return UIImage(cgImage: cgImage)
}

/// 等比例缩放图片，使其编码后数据不超过指定大小
private func compressImageIfNeeded(_ image: UIImage, maxBytes: Int = 10 * 1024 * 1024) throws -> UIImage {
    // 先检查 JPEG 大小，不超限就直接返回
    if let jpegData = image.jpegData(compressionQuality: 0.95), jpegData.count <= maxBytes {
        return image
    }

    // 超限了，逐步缩小直到 JPEG 不超限
    var current = image
    for i in 0..<5 {
        let scale: CGFloat = 0.8
        let newSize = CGSize(width: current.size.width * scale, height: current.size.height * scale)
        let renderer = UIGraphicsImageRenderer(size: newSize)
        let resized = renderer.image { _ in
            current.draw(in: CGRect(origin: .zero, size: newSize))
        }

        if let data = resized.jpegData(compressionQuality: 0.95), data.count <= maxBytes {
            print("[AI Debug] 图片超限，第\(i+1)次缩放至 \(Int(newSize.width))×\(Int(newSize.height))，JPEG 大小: \(data.count / 1024)KB")
            return resized
        }

        current = resized
    }

    // 兜底：强制缩放到长边 2048px
    let maxDim: CGFloat = 2048
    let ratio = min(maxDim / current.size.width, maxDim / current.size.height, 1.0)
    let finalSize = CGSize(width: current.size.width * ratio, height: current.size.height * ratio)
    let renderer = UIGraphicsImageRenderer(size: finalSize)
    let result = renderer.image { _ in
        current.draw(in: CGRect(origin: .zero, size: finalSize))
    }
    print("[AI Debug] 图片兜底缩放至 \(Int(finalSize.width))×\(Int(finalSize.height))")

    // 最终校验：如果仍然超限，说明图片无法在合理尺寸内压缩
    if let finalData = result.jpegData(compressionQuality: 0.95), finalData.count > maxBytes {
        print("[AI Debug] WARNING: 兜底缩放后仍超限 \(finalData.count / 1024)KB，放弃压缩")
        throw AIError.imageProcessingFailed
    }
    return result
}

/// 校验 HTTP 响应状态码，非 200 时抛出对应错误
private func validateHTTPResponse(_ response: HTTPURLResponse, data: Data) throws {
    guard response.statusCode == 200 else {
        let errorText = String(data: data, encoding: .utf8) ?? "Unknown error"
        print("[AI Debug] API错误: \(errorText)")
        if response.statusCode == 429 {
            let lower = errorText.lowercased()
            let isInsufficientBalance = lower.contains("insufficient")
                || lower.contains("balance")
                || lower.contains("quota")
                || lower.contains("billing")
                || lower.contains("payment")
                || errorText.contains("余额")
                || errorText.contains("欠费")
                || errorText.contains("额度")
            if isInsufficientBalance {
                throw AIError.insufficientBalance(errorText)
            }
            throw AIError.serverOverloaded(errorText)
        }
        throw AIError.apiError("HTTP \(response.statusCode): \(errorText)")
    }
}

// MARK: - 图像识别

func recognizeImage(_ image: UIImage, mode: RecognitionMode = .table, colorSystem: ColorSystem = .mard) async throws -> [AIRecognizedItem] {
    switch config.backend {
    case .cloud:
        guard !config.apiKey.isEmpty else {
            throw AIError.notConfigured
        }
    case .local:
        guard LocalModelManager.shared.isDownloaded(config.localModel) else {
            throw AIError.localModelNotDownloaded(config.localModel.displayName)
        }
    }

    // 预处理图片（减少水印影响）
    let processedImage = preprocessImage(image)

    // 打印 AI 配置信息
    print("[AI Debug] ========== AI 识别开始 ==========")
    print("[AI Debug] 识别方式: \(config.backend.rawValue)")
    if config.backend == .cloud {
        print("[AI Debug] AI 提供商: \(config.provider.rawValue)")
        print("[AI Debug] 模型: \(config.effectiveModel)")
        print("[AI Debug] API 地址: \(config.effectiveBaseURL)")
    } else {
        print("[AI Debug] 本地模型: \(config.localModel.displayName)")
    }
    print("[AI Debug] 原图尺寸: \(image.size), 处理后: \(processedImage.size)")
    print("[AI Debug] 识别模式: \(mode == .table ? "表格识别" : "图纸识别")")
    print("[AI Debug] 色号体系: \(colorSystem.rawValue)")

    if config.backend == .local {
        return try await recognizeWithLocalModel(image: processedImage, mode: mode, colorSystem: colorSystem)
    }

    // 如果图片数据超过 10MB，先等比例缩放
    let finalImage = try compressImageIfNeeded(processedImage)

    // 优先使用PNG格式（无损），如果太大则使用高质量JPEG
    // PNG对于表格文字识别效果更好，不会有JPEG压缩伪影
    let imageData: Data
    let mediaType: String

    if let pngData = finalImage.pngData() {
        if pngData.count < 10 * 1024 * 1024 {
            imageData = pngData
            mediaType = "image/png"
            print("[AI Debug] 使用PNG格式，大小: \(pngData.count / 1024)KB")
        } else {
            guard let jpegData = finalImage.jpegData(compressionQuality: 0.95) else {
                throw AIError.imageProcessingFailed
            }
            imageData = jpegData
            mediaType = "image/jpeg"
            print("[AI Debug] PNG太大，使用JPEG格式，大小: \(jpegData.count / 1024)KB")
        }
    } else if let jpegData = finalImage.jpegData(compressionQuality: 0.95) {
        imageData = jpegData
        mediaType = "image/jpeg"
        print("[AI Debug] 使用JPEG格式，大小: \(jpegData.count / 1024)KB")
    } else {
        throw AIError.imageProcessingFailed
    }

    let base64Image = imageData.base64EncodedString()
    print("[AI Debug] Base64长度: \(base64Image.count)")

    switch config.provider {
    case .kimi, .openai, .qwen:
        // Kimi、OpenAI、Qwen 使用相同的 API 格式（OpenAI 兼容）
        return try await recognizeWithOpenAI(base64Image: base64Image, mediaType: mediaType, mode: mode, colorSystem: colorSystem)
    case .anthropic:
        return try await recognizeWithAnthropic(base64Image: base64Image, mediaType: mediaType, mode: mode, colorSystem: colorSystem)
    case .gemini:
        return try await recognizeWithGemini(base64Image: base64Image, mediaType: mediaType, mode: mode, colorSystem: colorSystem)
    }
}

// MARK: - 连接测试

/// 真实地尝试一次网络/本地探测，返回延迟或中文失败原因。
/// 不吞错：每个失败分支都给出可读的中文 reason。
func testConnection() async -> TestConnectionResult {
    switch config.backend {
    case .local:
        // 本地：只看模型是否下载
        if LocalModelManager.shared.isDownloaded(config.localModel) {
            return .success(latencyMs: 0)
        } else {
            return .failure(reason: String(localized: "模型未下载，请先下载"))
        }
    case .cloud:
        guard !config.apiKey.isEmpty else {
            return .failure(reason: String(localized: "未填写 API Key"))
        }
        return await pingCloudProvider()
    }
}

/// 对当前 provider 做一次轻量 ping（优先 /models 列表接口，不行再 fallback 到对话接口）
private func pingCloudProvider() async -> TestConnectionResult {
    let session = Self.testConnectionSession
    let start = Date()

    do {
        let request = try buildPingRequest()
        let (data, response) = try await session.data(for: request)
        let latencyMs = Int((Date().timeIntervalSince(start)) * 1000)

        guard let http = response as? HTTPURLResponse else {
            return .failure(reason: String(localized: "服务器返回无效响应"))
        }

        if (200..<300).contains(http.statusCode) {
            return .success(latencyMs: latencyMs)
        }

        let bodyText = String(data: data, encoding: .utf8) ?? ""
        return .failure(reason: Self.humanReason(forHTTPStatus: http.statusCode, body: bodyText))
    } catch let urlError as URLError {
        return .failure(reason: Self.humanReason(forURLError: urlError))
    } catch {
        return .failure(reason: String(localized: "请求失败：\(error.localizedDescription)"))
    }
}

/// 构造一次轻量探测请求。
/// - Kimi / OpenAI / Qwen：GET {baseURL}/models（OpenAI 兼容）
/// - Anthropic：POST /v1/messages 带 max_tokens=1 的最小 ping
/// - Gemini：GET /models?key=...
private func buildPingRequest() throws -> URLRequest {
    let base = config.effectiveBaseURL

        HistoryManager.shared.setModelContext(container.mainContext)
        HistoryManager.shared.inventoryManager = manager
        AppLogger.shared.info("App", "history_context_set")  // 启动耗时探针：HistoryManager 上下文就绪（取数已转后台，不再阻塞此处）

        self.initialFatalErrorMessage = fatalErrorMessage

        // 初始化 TipKit —— 移出 App.init 同步路径。Tips.configure 冷启动要做 datastore 磁盘
        // 初始化（实测可达数百 ms），但它跟首帧无关（tips 是后续在具体页面按交互才弹），放在
        // 首帧前同步跑只会拖长白屏。改到后台 utility 队列异步配置；TipKit 仅要求 configure
        // 先于任意 tip 使用，启动后几百毫秒内不会触达任何 tip，延迟一拍无影响。
        Task.detached(priority: .utility) {
            do {
                try Tips.configure([
                    .displayFrequency(.daily),
                    .datastoreLocation(.applicationDefault)
                ])
            } catch {
                AppLogger.shared.error("TipKit", "初始化失败: \(error.localizedDescription)")
            }
        }
        AppLogger.shared.info("App", "app_init_completed")  // 启动耗时探针：App.init 同步段结束（首帧前）
    }

    var body: some Scene {
        WindowGroup {
            ContentView(shouldOpenScan: $shouldOpenScan)
                .environmentObject(inventoryManager)
                .environmentObject(sharedImageManager)
                .environmentObject(cloudSyncStatusManager)
                .environment(themeManager)
                .task {
                    let ctx = ModelContext(modelContainer)
                    do {
                        try themeManager.bootstrapBuiltinPresets(modelContext: ctx)
                    } catch {
                        AppLogger.shared.error("Theme", "bootstrap_builtin_failed", metadata: ["error": "\(error)"])
                    }
                    themeManager.loadOverridesFromDefaults()
                    themeManager.loadPendingDraftFromDefaults()
                    if themeManager.isDirty {
                        showingThemeRecoveryAlert = true
                    }
                }
                .alert("color_mode.dialog.recover_title", isPresented: $showingThemeRecoveryAlert) {
                    Button("color_mode.dialog.recover_keep") { /* keep draft state in memory */ }
                    Button("color_mode.dialog.recover_discard", role: .destructive) {
                        themeManager.discardDraft()
                    }
                } message: {
                    Text("color_mode.dialog.recover_message")
                }
                .onOpenURL { url in
                    handleIncomingURL(url)
                }
                .onAppear {
                    // 如果数据库初始化有异常，延迟弹出提示
                    if let msg = initialFatalErrorMessage {
                        modelContainerFatalError = msg
                    }

                    inventoryManager.performInitialLoadIfNeeded(reason: "rootView.onAppear")
                    AppLogger.shared.info("App", "root_view_appeared")
                    // App 启动时检查是否有待处理的共享图片
                    sharedImageManager.checkForPendingImage()

                    // 检查并执行每周自动备份
                    BackupManager.shared.checkAndPerformWeeklyBackupIfNeeded(inventoryManager: inventoryManager)
                    // 启动时检查 iCloud 状态
                    cloudSyncStatusManager.refreshAccountStatus()

                    // 静默检查远程公告
                    AnnouncementManager.shared.checkForAnnouncement()
                }
                .alert(
                    String(localized: "数据库异常"),
                    isPresented: Binding(
                        get: { modelContainerFatalError != nil },
                        set: { if !$0 { modelContainerFatalError = nil } }
                    )
                ) {
                    Button(String(localized: "我知道了")) {
                        modelContainerFatalError = nil
                    }
                } message: {
                    Text(modelContainerFatalError ?? "")
                }
                .onReceive(
                    NotificationCenter.default
                        .publisher(for: .NSPersistentStoreRemoteChange)
                        .receive(on: RunLoop.main)
                ) { _ in
                    // 仅在前台时处理远程变更，后台/非活跃阶段统一在恢复活跃时刷新
                    guard scenePhase == .active else {
                        AppLogger.shared.debug(
                            "CloudSync",
                            "remote_change_ignored",
                            metadata: ["scenePhase": "\(scenePhase)"]
                        )
                        return
                    }
                    AppLogger.shared.info("CloudSync", "remote_change_received")
                    inventoryManager.scheduleRefreshFromPersistentStore(reason: "remoteChangeNotification")
                }
        }
        .modelContainer(modelContainer)
        .onChange(of: scenePhase) { _, newPhase in
            AppLogger.shared.info("AppLifecycle", "scene_phase_changed", metadata: ["phase": "\(newPhase)"])
            switch newPhase {
            case .background:
                // 应用进入后台时立即保存数据，防止被系统杀死后数据丢失
                inventoryManager.cancelScheduledRefresh(reason: "scenePhase.background")
                print("[App] 应用进入后台，保存数据...")
                inventoryManager.saveData()
                HistoryManager.shared.saveDataImmediately()
                themeManager.flushPersistenceNow()
                // 停掉 displayThumbnail 后台迁移协调器 —— 释放 CPU + 让 saveData 在干净 context 上完成。
                // 协调器内部用 generation token 保证下次 .active start() 不会跟旧 task 抢资源。
                ThumbnailMigrationCoordinator.shared.stop()
            case .inactive:
                // .inactive 频繁出现（例如控制中心、系统弹窗），先取消待执行刷新；
                // 若首次加载已完成，则补一次保守保存，降低系统在 .inactive 直接终止时的数据丢失风险。
                print("[App] 应用进入非活跃状态")
                inventoryManager.cancelScheduledRefresh(reason: "scenePhase.inactive")
                if inventoryManager.hasCompletedInitialLoad {
                    inventoryManager.saveData()
                    HistoryManager.shared.saveDataImmediately()
                }
                themeManager.flushPersistenceNow()
                ThumbnailMigrationCoordinator.shared.stop()
            case .active:
                print("[App] 应用恢复活跃状态")
                if hasSeenInitialActivePhase {
                    // 前台恢复与远程通知共用同一防抖刷新队列，避免短时间重复全量加载
                    inventoryManager.scheduleRefreshFromPersistentStore(
                        reason: "scenePhase.active",
                        debounceSeconds: 0.25
                    )
                } else {
                    hasSeenInitialActivePhase = true
                    let hadCompletedInitialLoadBeforeActive = inventoryManager.hasCompletedInitialLoad
                    inventoryManager.performInitialLoadIfNeeded(reason: "scenePhase.active.initial")
                    if !hadCompletedInitialLoadBeforeActive && inventoryManager.hasCompletedInitialLoad {
                        inventoryManager.scheduleRefreshFromPersistentStore(
                            reason: "scenePhase.active.initialCatchUp",
                            debounceSeconds: 0.25
                        )
                    }
                }
                cloudSyncStatusManager.refreshAccountStatus()
                // 历史记录若在启动时加载失败（isDataLoaded 仍 false），前台恢复时补一次重试 ——
                // 否则失败后整 session 历史只在内存、saveDataImmediately 也被守卫跳过、退出即丢。
                HistoryManager.shared.reloadIfNeeded()
                // 启动 displayThumbnail 后台迁移协调器 —— 给老用户的大图后台 backfill 小图。
                // 协调器内部 5s 延迟 + 重入安全（已在跑就跳过）+ 失败自愈（下次启动从余量继续）。
                // **关键路径**：458 项目级用户在迁移完成前列表 fallback 现场降级，**已经**不会撞 jetsam，
                // 迁移只是把列表加载从 fallback CGImageSource 升级到直接读小图 JPEG。
                ThumbnailMigrationCoordinator.shared.start(inventoryManager: inventoryManager)
            @unknown default:
                break
            }
        }
    }

    /// 处理传入的 URL Scheme
    private func handleIncomingURL(_ url: URL) {
        // 处理 beadinventory://scan
        if url.scheme == "beadinventory" && url.host == "scan" {
            AppLogger.shared.info("DeepLink", "open_scan", metadata: ["url": url.absoluteString])
            // 检查共享图片
            sharedImageManager.checkForPendingImage()
            // 触发跳转到扫描页
            shouldOpenScan = true
        }
    }
}

/// 用户级 iCloud 同步偏好。
///
/// `userOptedOut == true` 时，`BeadInventoryApp.init()` 会用 `cloudKitDatabase: .none`
/// 创建 ModelContainer，App 仅使用本地 SQLite。CloudKit 上原有的数据**不会被删除**，

/// 编进 JSON（v1.x 起就这样，只是以前在 InventoryManager.projects 里现成有图）。
/// 在 cold-start 的 onAppear 同步路径里跑这玩意儿可能撞 scene-create watchdog，
/// 所以把执行延后一帧 + 走 Task：让首屏先 commit，避免首帧渲染期间被卡。
@MainActor func checkAndPerformWeeklyBackupIfNeeded(inventoryManager: InventoryManager) {
    let now = Date()

    // 获取上次备份日期
    if let lastBackupDate = UserDefaults.standard.object(forKey: lastBackupDateKey) as? Date {
        // 检查是否在同一周
        if Calendar.current.isDate(now, equalTo: lastBackupDate, toGranularity: .weekOfYear) {
            print("[BackupManager] 本周已备份，跳过")
            return
        }
    }

    // 推迟到下一次 runloop tick：让首屏 scene-create commit 先完成。
    // 注意：备份仍然要在 MainActor 上跑（SwiftData mainContext 限定主线程），
    // 但它不会再卡在第一帧 commit 里 —— iOS watchdog 不会因此再 0x8BADF00D。
    Task { @MainActor in
        performBackup(inventoryManager: inventoryManager)
    }
}

// MARK: - 执行备份

/// 创建备份
@discardableResult
@MainActor func performBackup(inventoryManager: InventoryManager) -> Bool {
    guard let backupDir = backupDirectory else {
        print("[BackupManager] 无法获取备份目录")
        return false
    }

    // 生成备份数据
    let backupData = createBackupData(from: inventoryManager)

    guard let jsonData = try? JSONSerialization.data(withJSONObject: backupData, options: [.prettyPrinted, .sortedKeys]) else {
        print("[BackupManager] 备份数据序列化失败")
        return false
    }

    // 生成文件名：backup_2024-01-15_周一.json
    let fileName = generateBackupFileName()
    let fileURL = backupDir.appendingPathComponent(fileName)

    do {
        try jsonData.write(to: fileURL)

        // 更新上次备份日期
        UserDefaults.standard.set(Date(), forKey: lastBackupDateKey)

        print("[BackupManager] 备份成功: \(fileName)")

        // 清理旧备份
        cleanupOldBackups()

        return true
    } catch {
        print("[BackupManager] 备份写入失败: \(error)")
        return false
    }
}

// MARK: - 备份数据生成

@MainActor private func createBackupData(from manager: InventoryManager) -> [String: Any] {
    var data: [String: Any] = [:]

    // 元数据
    data["backupDate"] = ISO8601DateFormatter().string(from: Date())
    data["appVersion"] = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "unknown"
    data["backupType"] = "weekly_auto"

    // 品牌数据
    data["brands"] = manager.brands.map { brand in
        [
            "id": brand.id.uuidString,
            "name": brand.name,
            "sortOrder": brand.sortOrder,
            "createdAt": ISO8601DateFormatter().string(from: brand.createdAt),
            "lowStockThreshold": brand.lowStockThreshold,
            "colorSystem": brand.colorSystem.rawValue
        ]
    }

    // 库存数据
    data["brandStocks"] = manager.brandStocks.map { stock in
        [
            "id": stock.id.uuidString,
            "brandId": stock.brandId.uuidString,
            "mardCode": stock.mardCode,
            "stock": stock.stock,
            "used": stock.used,
            "isHidden": stock.isHidden
        ]
    }

    // 项目数据
    //
    // 注意：自 v2.0.x 起 manager.projects 不再持有 thumbnail / finishedImage Data
    // （为避免 458 项目级用户加载即 ~200MB 内存撞 jetsam）。备份阶段才把图按需取出来 base64。
    // 一次只持有一张图的 Data，循环结束即释放，峰值内存 ≈ 单张最大图 + JSON 累积体积。
    data["projects"] = manager.projects.map { project in
        var projectData: [String: Any] = [
            "id": project.id.uuidString,
            "name": project.name,
            "date": ISO8601DateFormatter().string(from: project.date),
            "totalBeads": project.totalBeads,
            "isArchived": project.isArchived,
            "isPlanned": project.isPlanned,
            "colorSystem": project.colorSystem.rawValue
        ]
        if let brandId = project.brandId {
            projectData["brandId"] = brandId.uuidString
        }
        if let completedDate = project.completedDate {
            projectData["completedDate"] = ISO8601DateFormatter().string(from: completedDate)
        }
        if let executedDate = project.executedDate {
            projectData["executedDate"] = ISO8601DateFormatter().string(from: executedDate)
        }
        if let parentId = project.parentId {
            projectData["parentId"] = parentId.uuidString
        }
        // 按需从 SwiftData 取图（projects 缓存里已不含）。
        if let thumbnail = manager.fetchProjectThumbnailData(for: project.id) {
            projectData["thumbnail"] = thumbnail.base64EncodedString()
        }
        if let finishedImage = manager.fetchProjectFinishedImageData(for: project.id) {
            projectData["finishedImage"] = finishedImage.base64EncodedString()
        }
        // displayThumbnail：备份带就写小图，让 restore 直接拿来不用现场降级。
        // displayThumbnailProvided 标志让 restore 区分"老备份没这个字段"和"新备份显式说没小图"。
        projectData["displayThumbnailProvided"] = true
        if let displayThumbnail = manager.fetchProjectDisplayThumbnail(for: project.id) {
            projectData["displayThumbnail"] = displayThumbnail.base64EncodedString()
        }
        projectData["beadUsage"] = project.beadUsage.map { usage in
            [
                "colorCode": usage.colorCode,
                "quantity": usage.quantity,
                "isDeducted": usage.isDeducted
            ]
        }
        return projectData
    }

    // 自定义色号
    data["customColors"] = manager.customColors.map { color in
        [
            "id": color.id.uuidString,
            "colorCode": color.colorCode,
            "colorHex": color.colorHex,
            "colorName": color.colorName,
            "createdAt": ISO8601DateFormatter().string(from: color.createdAt),
            "updatedAt": ISO8601DateFormatter().string(from: color.updatedAt)
        ]
    }

    // 运输中记录
    data["purchaseRecords"] = manager.purchaseRecords.map { record in
        var recordData: [String: Any] = [
            "id": record.id.uuidString,
            "name": record.name,
            "date": ISO8601DateFormatter().string(from: record.date),
            "brandId": record.brandId.uuidString
        ]
        if let note = record.note {
            recordData["note"] = note
        }
        recordData["items"] = record.items.map { item in
            [
                "id": item.id.uuidString,
                "colorCode": item.colorCode,
                "quantity": item.quantity
            ]
        }
        return recordData
    }

