        ? (aggregates[project.id]?.usage.map { ($0.key, $0.value) } ?? [])
        : project.beadUsage.map { ($0.colorCode, $0.quantity) }
    let brandsInSystem = inventoryManager.brands.filter { $0.colorSystem == project.colorSystem }
