        var available = 0
        for brand in brandsInSystem {
            if let stock = inventoryManager.getStock(brandId: brand.id, mardCode: mardCode) {
                available += stock.available
            }
        }
        if available < usage.quantity { shortage += 1 }
    }
    return shortage
}

