893	+//
894	+//  InventoryManagerBlobFetchTests.swift
895	+//  BeadInventoryTests
896	+//
897	+//  覆盖 SwiftData blob 抗物化路径的两个回归点：
898	+//  1. fetchProjectThumbnailData 单列投影（fetchLimit + propertiesToFetch = [\.thumbnail]）
899	+//     后仍返回正确的 thumbnail 字节，未知 id 返回 nil。
900	+//  2. saveData 的 SDProjectRecord 全表 fetch 加 metadata propertiesToFetch 后，
901	+//     metadata 差分写回仍生效，且**不会**把同行的 blob 列清掉（saveData 自 v2.0.x
902	+//     起不写 blob 字段，本用例钉住"单列投影 + 部分物化对象写回"组合的正确性）。
903	+//
904	+
905	+import XCTest
906	+import SwiftData
907	+@testable import BeadInventory
908	+
909	+@MainActor
910	+final class InventoryManagerBlobFetchTests: XCTestCase {
911	+    private func makeContext() throws -> ModelContext {
912	+        let config = ModelConfiguration(isStoredInMemoryOnly: true, cloudKitDatabase: .none)
913	+        let container = try ModelContainer(for: SDProjectRecord.self, configurations: config)
914	+        return ModelContext(container)
915	+    }
916	+
917	+    private let thumbBytes = Data([0x01, 0x02, 0x03, 0x04])
918	+    private let finishedBytes = Data([0x0A, 0x0B])
919	+    private let displayBytes = Data([0x0C])
920	+
921	+    // MARK: - 单 blob fetch
922	+
923	+    func test_fetchProjectThumbnailData_returns_thumbnail_column_only_row() throws {
924	+        let ctx = try makeContext()
925	+        let record = SDProjectRecord(
926	+            name: "带图项目",
927	+            thumbnail: thumbBytes,
928	+            finishedImage: finishedBytes,
929	+            displayThumbnail: displayBytes
930	+        )
931	+        ctx.insert(record)
932	+        try ctx.save()
933	+
934	+        let m = InventoryManager(modelContext: ctx)
935	+        // 单列投影后仍取到正确 thumbnail（不是同行其它 blob 列的内容）
936	+        XCTAssertEqual(m.fetchProjectThumbnailData(for: record.id), thumbBytes)
937	+    }
938	+
939	+    func test_fetchProjectThumbnailData_unknown_id_returns_nil() throws {
940	+        let ctx = try makeContext()
941	+        ctx.insert(SDProjectRecord(name: "其它项目", thumbnail: thumbBytes))
942	+        try ctx.save()
943	+
944	+        let m = InventoryManager(modelContext: ctx)
945	+        XCTAssertNil(m.fetchProjectThumbnailData(for: UUID()))
946	+    }
947	+
948	+    func test_fetchProjectThumbnailData_project_without_thumbnail_returns_nil() throws {
949	+        let ctx = try makeContext()
950	+        let record = SDProjectRecord(name: "无图项目", finishedImage: finishedBytes)
951	+        ctx.insert(record)
952	+        try ctx.save()
953	+
954	+        let m = InventoryManager(modelContext: ctx)
955	+        XCTAssertNil(m.fetchProjectThumbnailData(for: record.id))
956	+    }
957	+
958	+    // MARK: - saveData metadata 投影写回
959	+
960	+    func test_saveData_metadata_projection_updates_metadata_and_preserves_blobs() throws {
961	+        let ctx = try makeContext()
962	+        let record = SDProjectRecord(
963	+            name: "原名",
964	+            totalBeads: 100,
965	+            thumbnail: thumbBytes,
966	+            finishedImage: finishedBytes,
967	+            displayThumbnail: displayBytes
968	+        )
969	+        ctx.insert(record)
970	+        try ctx.save()
971	+        let projectId = record.id
972	+
973	+        let m = InventoryManager(modelContext: ctx)
974	+        m.performInitialLoadIfNeeded(reason: "unitTest")
975	+        XCTAssertTrue(m.hasCompletedInitialLoad, "loadData 应成功完成")
976	+
977	+        guard let idx = m.projects.firstIndex(where: { $0.id == projectId }) else {
978	+            return XCTFail("loadData 后应能在内存缓存中找到项目")
979	+        }
980	+        // metadata-only 加载：内存缓存不应持有 blob
981	+        XCTAssertNil(m.projects[idx].thumbnail)
982	+
983	+        m.projects[idx].name = "改名后"
984	+        m.saveData()
985	+
986	+        // 全行重新取出验证：metadata 已更新、blob 列未被部分物化写回破坏
987	+        var descriptor = FetchDescriptor<SDProjectRecord>(
988	+            predicate: #Predicate { $0.id == projectId }
989	+        )
990	+        descriptor.fetchLimit = 1
991	+        guard let saved = try ctx.fetch(descriptor).first else {
992	+            return XCTFail("保存后项目应仍在持久层")
993	+        }
994	+        XCTAssertEqual(saved.name, "改名后")
995	+        XCTAssertEqual(saved.totalBeads, 100)
996	+        XCTAssertEqual(saved.thumbnail, thumbBytes)
997	+        XCTAssertEqual(saved.finishedImage, finishedBytes)
998	+        XCTAssertEqual(saved.displayThumbnail, displayBytes)
999	+    }
1000	+}
